SELECT bucket, set_cost_of_sales, set_operating_expenses, set_other_cost, set_product_sales, set_returns FROM (SELECT bucket, SUM(set_cost_of_sales) OVER (PARTITION BY CAST(DATE_TRUNC(bucket, YEAR) AS DATE) ORDER BY bucket) AS set_cost_of_sales, SUM(set_operating_expenses) OVER (PARTITION BY CAST(DATE_TRUNC(bucket, YEAR) AS DATE) ORDER BY bucket) AS set_operating_expenses, SUM(set_other_cost) OVER (PARTITION BY CAST(DATE_TRUNC(bucket, YEAR) AS DATE) ORDER BY bucket) AS set_other_cost, SUM(set_product_sales) OVER (PARTITION BY CAST(DATE_TRUNC(bucket, YEAR) AS DATE) ORDER BY bucket) AS set_product_sales, SUM(set_returns) OVER (PARTITION BY CAST(DATE_TRUNC(bucket, YEAR) AS DATE) ORDER BY bucket) AS set_returns FROM (SELECT CAST(DATE_TRUNC(posting_date, MONTH) AS DATE) AS bucket, COALESCE(SUM(CASE WHEN account_id IN ('5000', '5010', '5020', '5030', '5040', '5050', '5060', '5070', '5080', '5090') THEN CASE WHEN account_id IN ('5000', '5010', '5020', '5030', '5040', '5050', '5060', '5070', '5080', '5090') THEN CAST(amount AS BIGNUMERIC) END END), 0) AS set_cost_of_sales, COALESCE(SUM(CASE WHEN account_id IN ('6000', '6010', '6020', '6030', '6040', '6050', '6060', '6070', '6080', '6090', '6100', '6110', '6120', '6130', '6140') THEN CASE WHEN account_id IN ('6000', '6010', '6020', '6030', '6040', '6050', '6060', '6070', '6080', '6090', '6100', '6110', '6120', '6130', '6140') THEN CAST(amount AS BIGNUMERIC) END END), 0) AS set_operating_expenses, COALESCE(SUM(CASE WHEN account_id IN ('5900') THEN CASE WHEN account_id IN ('5900') THEN CAST(amount AS BIGNUMERIC) END END), 0) AS set_other_cost, COALESCE(SUM(CASE WHEN account_id IN ('4000', '4010', '4020', '4030', '4040', '4050', '4060', '4070', '4080', '4090') THEN CASE WHEN account_id IN ('4000', '4010', '4020', '4030', '4040', '4050', '4060', '4070', '4080', '4090') THEN -CAST(amount AS BIGNUMERIC) END END), 0) AS set_product_sales, COALESCE(SUM(CASE WHEN account_id IN ('4900') THEN CASE WHEN account_id IN ('4900') THEN CAST(amount AS BIGNUMERIC) END END), 0) AS set_returns FROM journal WHERE posting_date >= CAST('2025-01-01' AS DATE) AND posting_date < CAST('2025-07-01' AS DATE) GROUP BY CAST(DATE_TRUNC(posting_date, MONTH) AS DATE)) AS scan) AS windowed WHERE bucket >= CAST(DATE_TRUNC(CAST('2025-03-15' AS DATE), MONTH) AS DATE) ORDER BY bucket
